import random, sys, re
codons = {
'A':['GCT','GCC','GCA','GCG'],'C':['TGT','TGC'],'D':['GAT','GAC'],'E':['GAA','GAG'],
'F':['TTT','TTC'],'G':['GGT','GGC','GGA','GGG'],'H':['CAT','CAC'],'I':['ATT','ATC','ATA'],
'K':['AAA','AAG'],'L':['TTA','TTG','CTT','CTC','CTA','CTG'],'M':['ATG'],'N':['AAT','AAC'],
'P':['CCT','CCC','CCA','CCG'],'Q':['CAA','CAG'],'R':['CGT','CGC','CGA','CGG','AGA','AGG'],
'S':['TCT','TCC','TCA','TCG','AGT','AGC'],'T':['ACT','ACC','ACA','ACG'],'V':['GTT','GTC','GTA','GTG'],
'W':['TGG'],'Y':['TAT','TAC']}
aa_of={c:a for a,cs in codons.items() for c in cs}
stops={'TAA','TAG','TGA'}
MASK49=(1<<49)-1

def codon_bits(c):
    bits=0
    for ch in c:
        bits=(bits<<1)|(1 if ch in 'GC' else 0)
    return bits

def greedy(protein, seed=0, target=24.5, rand_eps=0.0):
    random.seed(seed)
    tail=0; seq=[]
    for i,aa in enumerate(protein):
        pos0=3*i
        best=None; bestcost=1e18; bestwin=None
        opts=codons[aa][:]
        random.shuffle(opts)
        for c in opts:
            bits=codon_bits(c)
            t=tail; cost=0.0; viol=0
            for j in range(3):
                b=(bits>>(2-j))&1
                win=(t<<1)|b
                if pos0+j+1>=50:
                    g=win.bit_count()
                    v=max(0,15-g,g-35)
                    viol+=v
                    cost+=v*v*1000.0
                    cost+=0.05*(g-25.0)**2
                t=win & MASK49
            gtail=t.bit_count()
            cost+=(gtail-target)**2
            cost+=random.random()*rand_eps
            if cost<bestcost:
                bestcost=cost; best=c; bestwin=t; bestviol=viol
        if best is None:
            return None,None,("no codon",i)
        if bestviol>0:
            return None,None,("violation at",i,bestviol)
        seq.append(best); tail=bestwin
    s=''.join(seq)
    return s,tail,None

def validate(protein, seq):
    assert len(seq)==3*len(protein)
    trans=''.join(aa_of.get(seq[i:i+3],'X') for i in range(0,len(seq),3))
    assert trans==protein, [(i,a,b) for i,(a,b) in enumerate(zip(trans,protein)) if a!=b][:5]
    assert seq[:3]!='ATG' and seq[-3:] not in stops
    vals=[sum(1 for c in seq[i:i+50] if c in 'GC') for i in range(len(seq)-49)]
    assert min(vals)>=15 and max(vals)<=35, (min(vals),max(vals))
    for i in range(0,len(seq),3): assert seq[i:i+3] not in stops
    return min(vals),max(vals),sum(vals)/len(vals)

def build(components, linkers):
    out=[]
    for i,c in enumerate(components):
        if i>0: out.append(linkers[i-1])
        out.append(c)
    return ''.join(out)

if __name__=='__main__':
    flag="DYKDDDDK"
    clover_full="GSSHHHHHHSSGENLYFQGHMVSKGEELFTGVVPILVELDGDVNGHKFSVRGEGEGDATNGKLTLKFICTTGKLPVPWPTLVTTFGYGVACFSRYPDHMKQHDFFKSAMPEGYVQERTISFKDDGTYKTRAEVKFEGDTLVNRIELKGIDFKEDGNILGHKLEYNFNSHNVYITADKQKNGIKANFKIRHNVEDGSVQLADHYQQNTPIGDGPVLLPDNHYLSHQSALSKDPNEKRDHMVLLEFVTAAGITHGMDELYK"
